/*! \brief First public W6 window that can reach the order-wrap region. */
/*! \def ECDHP256_GENERATOR_W6_PROTECTED_START
 * \brief P-256 generator w6 protected start.
 */
#define ECDHP256_GENERATOR_W6_PROTECTED_START 42U

